#include <bits/stdc++.h>
using namespace std;

int main() {
	int n, q;
	cin >> n >> q;
	vector<int> L(n), R(n);
	for (int i = 1; i < n; i++) cin >> L[i];
	for (int i = 0; i < n - 1; i++) cin >> R[i];
	vector<int> A = L, B = R;
	for (int i = n - 2; i >= 0; i--) A[i] = min(A[i], A[i + 1]);
	for (int i = 1; i < n; i++) B[i] = min(B[i], B[i - 1]);
	while (q--) {
		int s, t;
		cin >> s >> t;
		s--; t--;
		if (s < t) {
			int ans = R[s];
			if (s > 0) ans = min(ans, L[s] + B[s - 1]);
			cout << ans << '\n';
		}
		else {
			int ans = L[s];
			if (s < n - 1) ans = min(ans, R[s] + A[s + 1]);
			cout << ans << '\n';
		}
	}
}
